window.SAQ_PAPER_QUESTIONS["2020-1-pah"]=[{"number":1,"title":"","stemText":"One of your residents has approached you for advice. She has seen a 45 year old woman with two weeks of increasing diplopia and general fatigue. The diplopia is binocular.","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential causes for this problem. For each, list a supportive examination finding\nand a supportive investigative finding. (12 marks) Potential cause Examination finding Investigative finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Myasthenia Gravis</td><td>Ptosis, muscle palsies, (many others)</td></tr><tr><td>Antibodies against AChR</td><td></td></tr><tr><td>3rd N palsy</td><td>Eye deviated out Intracranial Aneurysm on CTA</td></tr><tr><td>Thyroid Disease</td><td>Lid retraction/Exopthalmus etc Raised T hormone/Ab etc</td></tr><tr><td>CNS disease (ie MS)</td><td>Focal neurology Abnormal imaging ie MRI</td></tr><tr><td>Orbital disease ie tumour</td><td>Loss of red reflex etc Mass on CT</td></tr><tr><td>Others ok…</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 15 year old boy has been brought to the ED with a right ankle injury sustained while playing\nfootball. There is a 3cm wound over the lateral aspect of the ankle.","parts":[{"id":"a","label":"Part A","prompt":"rays are provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List 3 abnormalities show on the x-rays. (3 marks)\n1) 2)"},{"id":"c","label":"Part C","prompt":"Your hospital does not provide a paediatric orthopaedic service."},{"id":"d","label":"Part D","prompt":"State 6 key components of your management of the patient. (6 marks)\n1) 2) 3) 4) 5) 6)"},{"id":"e","label":"Part E","prompt":"List 3 potential complications of this injury. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"}],"propPages":["asset:img564fcaa73bfba484d9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>IV Antibiotics for soft tissue prophylaxis ie cephazolin 2gm tds </strong></div><div class=\"answer-line\">Arrange transfer to paediatric orthopaedic centre for OT</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Septic arthritis/ Osteomyelitis/ Wound Infection</div><div class=\"answer-line\">Growth Plate arrest</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Wound washout to debride foreign debris and dilute contamination</div><div class=\"answer-line\">Immobilise at 90deg in plaster slab, elevation</div><div class=\"answer-line\"><strong>IV Antibiotics for soft tissue prophylaxis ie cephazolin 2gm tds </strong></div><div class=\"answer-line\">Arrange transfer to paediatric orthopaedic centre for OT</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Septic arthritis/ Osteomyelitis/ Wound Infection</div><div class=\"answer-line\">Growth Plate arrest</div><div class=\"answer-line\">Early arthritis/ Loss of function</div><div class=\"answer-line\">Chronic Pain/ CRPS</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":3,"title":"","stemText":"You have been asked to write a protocol for the investigation of possible pulmonary embolism in pregnant patients.","parts":[{"id":"a","label":"Part A","prompt":"List 4 steps you would undertake prior to the drafting of this protocol. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"For each investigation listed, state its utility for investigation of PE in pregnancy. (6 marks) Investigation Utility"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["dimer Chest x-ray CTPA V/Q scan Duplex USS lower limbs Bedside echocardiogram"],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Establish current practice ie audit</div><div class=\"answer-line\">Enquire about peer practice at similar sites</div><div class=\"answer-line\">Review current standards of care (college guidelines/statements)</div><div class=\"answer-line\">Establish working party of invested stakeholders</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>D-Dimer</td><td>Unclear – ‘normal’ D-dimer higher in pregnancy.  May be role for trimester</td></tr><tr><td>cutoffs – negative D-Dimer adequate to exclude if Wells score &lt;4.</td><td></td></tr><tr><td>CXR</td><td>May demonstrate alternate pathology; rarely diagnostic</td></tr><tr><td>CTPA</td><td>Highly sensitive for large/sub-segmental PE.  Contrast and radiation risk to</td></tr><tr><td>fetus</td><td></td></tr><tr><td>V/Q Scan</td><td>Can be diagnostic if no lung disease. Lower fetal radiation exposure cf CTPA</td></tr><tr><td>Duplex Scan LL</td><td>Normal USS insufficient to exclude PE.  If DVT present obviates need for</td></tr><tr><td>radiation exposure as diagnosis made.</td><td></td></tr><tr><td>Bedside ECHO</td><td>Normal ECHO insufficient to exclude PE.  Increased Rt-sided cardiac</td></tr><tr><td>pressures can be normal in pregnancy with physiological changes</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 65 year old man has presented to your tertiary ED with 3 hours of central chest pain.\nHis ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 5 abnormalities on the ECG. (5 marks)\n1) 2) 3) 4) 5)"},{"id":"b","label":"Part B","prompt":"State your overall impression of this ECG, including the clinical relevance. (2 marks)"},{"id":"c","label":"Part C","prompt":"State 5 key components in his initial management. (5 marks)\n1) 2) 3) 4) 5) The patient looks pale and sweaty. He has severe shortness of breath. His chest x-ray is provided in the PROPS BOOKLET."},{"id":"d","label":"Part D","prompt":"Give your interpretation of the x-ray, supported by 3 radiological abnormalities. (4 marks)\nHis vital signs are:\n\nGCS\nE4 V4 M6\n\nBP\n80/45 mmHg\n\nRR\n/min O2 sats 85% 15L O2 via NRB You have decided that the patient needs to be intubated as part of his further management."},{"id":"e","label":"Part E","prompt":"List 4 difficulties you anticipate in the peri-intubation period. State your specific\nmanagement strategy to mitigate each difficulty. (8 marks) Difficulty Management strategy"}],"propPages":["asset:img3e17def44385c1e029","asset:imgcfa61a3210036e861a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>17/24</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Atrial Fibrillation, rate 84/min</div><div class=\"answer-line\">Multifocal PVCs throughout</div><div class=\"answer-line\">Anterolateral STEMI V2-V6, I, aVL</div><div class=\"answer-line\">Inferior ST depression</div><div class=\"answer-line\">Left Axis deviation with criteria for LAFB (qR in I, S in III)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Acute Anterolateral STEMI meeting reperfusion criteria </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – IV Morphine dose</div><div class=\"answer-line\">Aspirin 300mg</div><div class=\"answer-line\">Ticagrelor 180mg</div><div class=\"answer-line\">IV Heparin 5000units or 60u/kg</div><div class=\"answer-line\"><strong>Urgent referral for PCI  </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Supportive Findings:</div><div class=\"answer-line\">Perihilar congestion (“batwinging”)</div><div class=\"answer-line\">Kerley “b” lines</div><div class=\"answer-line\">Upper lobe vascular diversion</div><div class=\"answer-line\">Cardiomegaly</div><div class=\"answer-line\">Lack of chronic features ie no effusions</div><div class=\"answer-line\">Fluid in horizontal fissure</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Pre-Oxygenation</td><td>Utilise continuous hi-flow O2 through induction via BVM/NRB and</td></tr><tr><td colspan=\"2\">hiFlow Nasal Cannulae or NIV;</td></tr><tr><td colspan=\"2\">maintain at 30deg</td></tr><tr><td>Rapid Desaturation</td><td>Maintain hiflow nasal O2 throughout intubation; keep at 30deg</td></tr><tr><td colspan=\"2\">Bag through apnoea</td></tr><tr><td>Cardiovascular collapse</td><td>Commence adrenaline infusion IV; titrate to SBP &gt;90mmHg</td></tr><tr><td colspan=\"2\">Reduced dose of induction agent</td></tr><tr><td colspan=\"2\">Avoid vasodilating agents</td></tr><tr><td colspan=\"2\">Copious secretions/difficult view Use DL, suction ready</td></tr><tr><td>Difficult to bag</td><td>Two-person technique</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 23 year old man has presented to the ED with dysuria.","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses for this problem. For each diagnosis, list an examination\nfinding that would support its presence. (8 marks) Differential diagnosis Examination finding"},{"id":"b","label":"Part B","prompt":"List 4 investigations you might perform. Provide clinical justification for each\ninvestigation. (4 marks) Investigation Justification"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cystitis</td><td>Fever; suprapubic tenderness</td></tr><tr><td>Epididymo-orchitis</td><td>scrotal erythema/ testicular swelling</td></tr><tr><td>Urethritis</td><td>purulent discharge</td></tr><tr><td>Renal Colic</td><td>Haematuria/Flank Tenderness</td></tr><tr><td>Appendicitis</td><td>Focal Peritonism RLQ</td></tr><tr><td>Testicular Torsion</td><td>High-riding, transverse testicular lie; loss of cremasteric reflex</td></tr><tr><td>2.</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Confirm cystitis/causative organism/guide therapy</td><td></td></tr><tr><td><strong>PCR for STIs</strong></td><td>Confirm diagnosis, indicate need for contact tracing</td></tr><tr><td>USS Scrotum</td><td>Exclude testicular torsion/abscess/tumour</td></tr><tr><td>USS renal tracts</td><td>Exclude hydronephrosis/hydroureter</td></tr><tr><td>CT KUB</td><td>Confirm renal colic/exclude obstruction</td></tr><tr><td>Less common</td><td></td></tr><tr><td>Blood Cultures</td><td>If febrile, unwell – to guide therapy</td></tr><tr><td>Renal function</td><td>something good</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 12 month old boy has been brought to the ED after accidentally tipping a boiling jug of water on himself at home. A clinical photograph has been provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State 3 important features of this burn demonstrated in the photograph. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 3 options for analgesia including doses. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ You are helping your registrar assess the extent of the burn."},{"id":"c","label":"Part C","prompt":"Complete the following table regarding the specific clinical features of varying burn severity. (4 marks) Burn severity Specific clinical features Superficial Superficial partial thickness Deep partial thickness Full thickness"},{"id":"d","label":"Part D","prompt":"Describe 2 methods for first aid in this patient. (2 marks)\n1) 2)"}],"propPages":["asset:img90b3f803a4d802f70b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Large area erythema involving upper limb (sparing hand), face and trunk</div><div class=\"answer-line\">Blistering evidence of desquamation to UL and trunk</div><div class=\"answer-line\">Normal skin appears well perfused</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Intranasal Fentanyl 1.5 mcg/kg</div><div class=\"answer-line\">IV Fentanyl 1mcg/kg</div><div class=\"answer-line\">IV Morphine 0.1mg/kg</div><div class=\"answer-line\">Oral analgesia OK at appropriate doses but <strong>must have one parenteral</strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Burn Type</td><td>Specific Features</td></tr><tr><td>Superficial</td><td>Painful, no blisters</td></tr><tr><td>Superficial Partial</td><td>Blisters</td></tr><tr><td>Deep Partial</td><td>Absent cap refill, pale in colour</td></tr><tr><td>Full thickness</td><td>Leathery, Painless</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Tap water irrigation</div><div class=\"answer-line\">Other cooling methods – wet towels etc</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"You are managing a 32 year old woman who has sustained a major pelvic fracture after a motor vehicle accident. CT scan has demonstrated a grade 3 lateral compression fracture with active bleeding from a branch of the left internal iliac artery. This is an isolated injury. The patient has no past medical problems. You have arranged for embolisation of the bleeding vessel in the angiography suite. A coagulation profile was taken and is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give your interpretation of these results. (2 marks)"},{"id":"b","label":"Part B","prompt":"Based on these results, state 3 components of your further management of the patient’s resuscitation. Include end-points. (3 marks) 1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 3 additional laboratory targets you would aim for in your ongoing resuscitation.\n(3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List the approximate volume of each of the blood products given in the table. (4 marks) Blood product Approximate volume (mL) 1 unit packed red blood cells 1 bag pooled platelets (4 units) 1 unit fresh frozen plasma 1 unit cryoprecipitate"}],"propPages":["asset:imgbbebd0c3eaaf7e79bd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Elevated PT/APTT with depleted platelets / fibrinogen</div><div class=\"answer-line\">Consistent with Trauma-Induced Coagulopathy (COT) or DIC</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Platelet transfusion to achieve platelets &gt;50 (in actively bleeding patient)</div><div class=\"answer-line\">FFP to replace coagulation factors aiming INR &lt;1.5</div><div class=\"answer-line\">Cryoprecipitate OR Fibrinogen Concentrate to achieve Fibrinogen &gt;1.5</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Additional Lab targets</div><div class=\"answer-line\">pH &gt; 7.2</div><div class=\"answer-line\">iCa &gt; 1</div><div class=\"answer-line\">Hb &gt; 80</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>PRBCs</td><td>260 +/- 15mls</td></tr><tr><td>Platelets</td><td>367 +/- 16mls</td></tr><tr><td>FFP</td><td>278 +/- 13 mls</td></tr><tr><td colspan=\"2\">Cryoprecipitate 36 +/- 2mls</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 78 year old man has presented to hospital with low back pain. He has a history of myeloma.","parts":[{"id":"a","label":"Part A","prompt":"List 5 features of your examination that would be consistent with cauda equina syndrome.\n(5 marks) 1) 2) 3) 4) 5) Your assessment is not consistent with cauda equina syndrome. The patient had a serum electrolyte panel performed. The serum corrected calcium level is 3.2 mmol/L (ref range 2.10 - 2.60)."},{"id":"b","label":"Part B","prompt":"List 3 possible sequelae of severe hypercalcaemia other than bone related pain. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 3 treatment options for severe hypercalcaemia. (3 marks)\n1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Variable LL sensory loss</div><div class=\"answer-line\">Variable LL motor weakness</div><div class=\"answer-line\">Loss reflexes</div><div class=\"answer-line\"><strong>Saddle Anaesthesia </strong></div><div class=\"answer-line\"><strong>Decreased anal tone </strong></div><div class=\"answer-line\">Urinary retention</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Calculi formation ie renal stones</div><div class=\"answer-line\">Constipation</div><div class=\"answer-line\">Abdominal Pains</div><div class=\"answer-line\">Confusion/Stupor/Coma</div><div class=\"answer-line\">(not accepting <em>moans</em> and <em>groans</em>…)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Bisphosphonate therapy ie pamidronate IV infusion</div><div class=\"answer-line\">Calcitonin 4u/kg subcut</div><div class=\"answer-line\">Frusemide if volume replete</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You are working in a rural ED. You have been notified of the impending arrival of a 29 year old pregnant woman who is in labour at 36 weeks gestation. There is no obstetric service on site.","parts":[{"id":"a","label":"Part A","prompt":"List 5 steps in your preparation to receive this patient. (5 marks)\n1) 2) 3) 4) 5) Delivery of the child occurred in the ambulance prior to arrival. The umbilical cord was clamped and cut by the paramedic team. The child appears well. The mother has ongoing vaginal blood loss. The placenta has not been delivered. The patient’s vital signs are:\n\nGCS\nPulse 100 /min\n\nBP\n100/50 mmHg O2 sats 99% room air"},{"id":"b","label":"Part B","prompt":"List 4 key aspects of the management of the patient. (4 marks)\n1) 2) 3) 4)\nPAH 2020.1 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/9</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">Preparation steps:</td></tr><tr><td colspan=\"3\">Establish areas –</td></tr><tr><td colspan=\"3\">for mother</td></tr><tr><td colspan=\"3\">for baby</td></tr><tr><td colspan=\"3\">Establish teams –</td></tr><tr><td colspan=\"3\">include midwife and obstetrics/Gynae for mother</td></tr><tr><td colspan=\"3\">Include paediatrician for baby</td></tr><tr><td colspan=\"3\">Equipment:</td></tr><tr><td>For mother</td><td>–</td><td>Equipment to facilitate delivery (analgesia, gloves, towels, etc)</td></tr><tr><td>-</td><td>For after delivery: Syntocinon</td><td></td></tr><tr><td>-</td><td>For complications</td><td></td></tr><tr><td>For baby</td><td>-</td><td>Warming area ie humidicrib, Vitamin K, Oxygenation equipment ie</td></tr><tr><td colspan=\"3\">neopuff or similar</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Exclude twin pregnancy</div><div class=\"answer-line\">Syntocinon 10u IM or 40u in 1lt N/S IV titrated</div><div class=\"answer-line\">Fundal massage to achieve uterine contraction</div><div class=\"answer-line\"><strong>Controlled cord traction to deliver placenta </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 40 year old man has presented to the ED with progressive lethargy for the last 4 days.\nHe has a background of spina bifida. An arterial blood gas has been provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List the two acid-base disturbances demonstrated on the blood gas and provide supporting evidence. (4 marks)\nDisturbance 1\nSupporting evidence\nDisturbance 2\nSupporting evidence"},{"id":"b","label":"Part B","prompt":"List 4 differential diagnoses for the METABOLIC disturbance shown. For each, state how\nyou will determine its presence from your assessment (history, examination or investigation). (8 marks) Differential diagnosis Assessment feature"}],"propPages":["asset:img3dbe9a51819ab5b4ff"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">: HCO3 19, Anion Gap not raised Delta Ratio not indicated ie all loss of base</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>: Respiratory Acidosis</td><td></td></tr><tr><td>Supporting Evidence</td><td>: Expected CO2 35.5 (actual 50).</td></tr><tr><td>2.</td><td></td></tr><tr><td>Differentials would include anything that leads to loss of bicarb rich solutions</td><td></td></tr><tr><td>Ie</td><td></td></tr><tr><td>Diarrhoeal losses/malabsorptive states – history of diarrhea / high stomal output</td><td></td></tr><tr><td>Urinary diversion – Hx ureteric surgery / scars / stoma</td><td></td></tr><tr><td>Renal Tubular Acidoses – known addisons disease, drug abuse ie NSAIDs, known renal disease</td><td></td></tr><tr><td>Acetazolamide therapy – medication history, recent issues with IIH or glaucoma</td><td></td></tr><tr><td>Excess chloride ie saline therapy – fluid balance chart</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 5 year old boy has been brought to triage with a rash. The triage nurse is concerned the patient may have measles.","parts":[{"id":"a","label":"Part A","prompt":"List 2 findings on history that would make measles likely. (2 marks)\n1) 2)"},{"id":"b","label":"Part B","prompt":"List 4 examination findings that would be consistent with measles. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ You agree that measles is likely."},{"id":"c","label":"Part C","prompt":"State 4 measures you will take to manage the patient’s journey through the ED. (4 marks)\n1) 2) 3) 4)"},{"id":"d","label":"Part D","prompt":"List 2 serious complications of measles infection. (2 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Known measles contact</div><div class=\"answer-line\">Non-immunised or immunosuppressed</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">High fever</div><div class=\"answer-line\">Non-purulent conjunctivitis with scleral injection</div><div class=\"answer-line\"><strong>Morbilliform rash, usually starting at scalp/hairline </strong></div><div class=\"answer-line\">Koplik spots</div><div class=\"answer-line\">Rhinorrhoea</div><div class=\"answer-line\">Dry cough</div><div class=\"answer-line\">Pharyngitis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Place in negative-pressure room</div><div class=\"answer-line\">Staff to wear strict PPE</div><div class=\"answer-line\">Minimise testing/provocation of potential airborne spread</div><div class=\"answer-line\">Ensure staff aware of possible measles case, assign immunocompetent, immunized staff to provide</div><div class=\"answer-line\">cares</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pneumonia</div><div class=\"answer-line\">Encephalitis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"An 88 year old man has been found unconscious in his house by a neighbour.\nOn arrival to the ED he has a GCS of 3. A slice from a CT scan of his head is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 7 abnormalities evident on the CT scan. (7 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________ 6)________________________________________________________________________________ 7)________________________________________________________________________________ The patient’s family have arrived. They are waiting to talk to you about the patient’s condition."},{"id":"b","label":"Part B","prompt":"List 6 components of your history that will have significance in guiding further\nmanagement of this patient. (6 marks) 1) 2) 3) 4) 5) 6) After consultation with the family, it has been decided that palliative care would be the most appropriate course of action for this man."},{"id":"c","label":"Part C","prompt":"State 5 features of your palliative care plan. (5 marks)\n1) 2) 3) 4) 5)"}],"propPages":["asset:img7b86d931bfafdc93f5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>12/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Rt sided extraaxial hyperdensity crossing suture lines cf <strong>acute Rt subdural haemorrhage </strong></div><div class=\"answer-line\">Subfalcine herniation</div><div class=\"answer-line\">Rt ventricular effacement at temporal and occipital horns</div><div class=\"answer-line\"><strong>Midline shift to left  </strong></div><div class=\"answer-line\">Left sided dilation of occipital horn of lateral ventrical cf hydrocephalus – likely obstructive from MLS</div><div class=\"answer-line\">Left PCA territory ischaemia from trans-tentorial temporal lobe herniation</div><div class=\"answer-line\">Loss of grey-white differentiation on right</div><div class=\"answer-line\">Loss of sulcal spaces indicative of raised ICP</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pre-morbid quality of life</div><div class=\"answer-line\">Previously expressed patient wishes</div><div class=\"answer-line\">Existing formal documents ie ARP/AHD</div><div class=\"answer-line\">Presence of life-limiting comorbidities</div><div class=\"answer-line\">Cognitive status</div><div class=\"answer-line\">Medications (particularly anticoagulants)</div><div class=\"answer-line\">Allergies</div><div class=\"answer-line\">Others accepted if reasonable (must be HISTORY)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Private room</div><div class=\"answer-line\">Explain the anticipated clinical course</div><div class=\"answer-line\">Family have opportunity to be present with patient throughout</div><div class=\"answer-line\">Consistent nursing presence</div><div class=\"answer-line\">Stop any life-sustaining therapies</div><div class=\"answer-line\">Offer any religious supports ie chaplain/priest</div><div class=\"answer-line\">Proactive treatment with analgesics/sedatives ie morphine/midazolam at any suggestion of agitation</div><div class=\"answer-line\">Others acceptable here if reasonable.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 47 year old woman has presented with right sided upper abdominal pain for the last 24 hours. Liver function tests have been provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State your likely diagnosis, supported by an explanation of the blood results. (2 marks)"},{"id":"b","label":"Part B","prompt":"List and justify 5 further investigations you may perform. (5 marks)\nInvestigation Justification After a short period of time in the ED, the patient has complained of increasing pain and has\ndeveloped a fever of 39.5 degrees.\nHer other vital signs are:\n\nGCS\nPulse 110 /min\n\nBP\n85/45 mmHg\n\nRR\n/min O2 sats 98% room air"},{"id":"c","label":"Part C","prompt":"List 4 key aspects of your management of the patient. Include end-points where\nappropriate. (4 marks) 1) 2) 3) 4) As part of your management, you have decided to insert a central venous line."},{"id":"d","label":"Part D","prompt":"List 3 potential complications of central venous line insertion. For each, state the action you will take to prevent the complication. (6 marks) Complication Preventative action"}],"propPages":["asset:img56fae04f1b72903e85"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>13/17</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Acute ascending cholangitis</div><div class=\"answer-line\">Conjugated hyperbilirubinaemia</div><div class=\"answer-line\">Elevated GGT/ALP &gt;&gt; Transaminases</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Hepatic/biliary USS</strong> – obstructing cause ie stone, pancreatic head mass/tumour</div><div class=\"answer-line\">Blood Cultures – identify complicating organisms/guide therapy</div><div class=\"answer-line\">B-hCG – female of fertile age – will impact available therapies and invasive strategies</div><div class=\"answer-line\">Lipase – if suspected pancreatitis or pancreatic duct obstruction as cause</div><div class=\"answer-line\">Renal function – exclude complicating renal injury which may guide antimicrobial choice</div><div class=\"answer-line\">CT – if no obstructing stone/cause seen on USS can demonstrate or define intrahepatic cause ie PSC,</div><div class=\"answer-line\">hepatic abscess/tumour</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – Morphine IV 2.5mg repeat to comfort</div><div class=\"answer-line\"><strong>Antibiotics </strong>– as per eTG or local guidelines</div><div class=\"answer-line\">IV fluid resuscitation – 0.9% saline 10ml/kg repeat to MAP &gt;65</div><div class=\"answer-line\">Definitive management ie ERCP for source control</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Infection – strict sterile conditions</td><td>Pneumothorax – ultrasound guidance, check xray post procedure</td></tr><tr><td>Vascular injury – direct visualization of guidewire and central line in vessel</td><td>Guidewire-induced arrhythmia – cardiac monitoring throughout procedure with careful guidewire</td></tr><tr><td>insertion</td><td>Guidewire embolism – contact with guidewire throughout procedure</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 2 year old girl has been brought to the ED after being found in the kitchen with an empty bottle of liquid paracetamol.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your history or examination that will guide your risk assessment.\n(4 marks) 1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"State the conditions required for the following strategies. (4 marks)"},{"id":"g","label":"Part G","prompt":"State the indication for modification of the dose of the second bag. (1 mark)"},{"id":"h","label":"Part H","prompt":"List 2 conditions that should be met for cessation of N-acetylcysteine treatment. (2 marks) 1) 2)"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["No investigation required","Single paracetamol level only","Repeated paracetamol levels","Initiation of N-acetylcysteine prior to paracetamol level being assessed Following your assessment, N-acetylcysteine was commenced with a planned 2 bag regimen."],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Maximum ingested dose</div><div class=\"answer-line\"><strong>Patient weight </strong></div><div class=\"answer-line\">Probable time of ingestion</div><div class=\"answer-line\">Signs of established toxicity ie jaundice/tender liver etc.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">No investigation: Max ingestion possible &lt;200mg/kg</div><div class=\"answer-line\">Single level only: 2-4 hour level &lt;150mg/kg or 4-8hr level below treatment line</div><div class=\"answer-line\">Repeated levels: 2-4 hr level &gt;150mg – repeat at 4hrs</div><div class=\"answer-line\">Presentation after 8hrs post ingestion</div></section><section class=\"answer-part\"><h5>Part G</h5><div class=\"answer-line\">Paracetamol level double the treatment line at that time point</div></section><section class=\"answer-part\"><h5>Part H</h5><div class=\"answer-line\">ALT normal or decreasing AND</div><div class=\"answer-line\">Paracetamol &lt;10</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 60 year old man has presented to the ED with abdominal pain and vomiting.\nAn abdominal x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the main pathology demonstrated and provide 3 supportive radiological findings. (4 marks) Main pathology Supportive findings"},{"id":"b","label":"Part B","prompt":"List 4 potential causes of this problem. (4 marks)"},{"id":"c","label":"Part C","prompt":"List 4 further investigations you would perform, with justification. (4 marks)\n1) 2) 3) 4)"}],"propPages":["asset:img6ed7983c28b5adfde9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Dilated centrally located loops of bowel</div><div class=\"answer-line\">Air-fluid levels suggestive of obstruction to flow/stasis</div><div class=\"answer-line\">Lack of gas in large bowel/Rectum</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Adhesions</div><div class=\"answer-line\">Herniae</div><div class=\"answer-line\">Intussusception</div><div class=\"answer-line\">Lymphoma</div><div class=\"answer-line\">Strictures</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">CT Abdomen to delineate focal cause of obstruction</div><div class=\"answer-line\">Renal function to exclude pre-renal renal injury from volume losses (vomiting + 3rd spacing)</div><div class=\"answer-line\">Venous blood gas to assess for metabolic status given vomiting / assess lactate given pain and</div><div class=\"answer-line\">obstruction</div><div class=\"answer-line\">CXR/Gp &amp; Hld for perioperative assessment/optimization</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 9 year old boy has been brought to the ED with abdominal pain after falling off his pushbike. He has a tender left upper quadrant (LUQ) on examination. An image from his FAST scan (LUQ view) is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List the major abnormalities in this image. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 options for definitive management of this injury. For each option state the clinical indication for its adoption. (6 marks) Option Clinical indication"},{"id":"c","label":"Part C","prompt":"List 3 limitations of the FAST scan in the assessment of blunt abdominal trauma. (3 marks) 1) 2) 3)"}],"propPages":["asset:imgd68d4badac66a4c5c3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Large volume free fluid surrounding spleen cf blood</div><div class=\"answer-line\">Splenic Laceration</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Embolisation</td><td>Blush CTA</td></tr><tr><td>Splenectomy</td><td>Bleeding not amenable to embolization; lack of IR availability, hypotensive</td></tr><tr><td>Conservative</td><td>Haemodynamic stability</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Operator dependent</div><div class=\"answer-line\">Unlikely to provide information as to underlying injury pattern</div><div class=\"answer-line\">Poor at visualizing hollow viscous injury</div><div class=\"answer-line\">Risk of false-negatives early in presentation</div><div class=\"answer-line\">(In general) provides qualitative information rather than quantitative/injury classification</div><div class=\"answer-line\">Many others here….</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 65 year old woman has presented with severe respiratory distress. She has a history of chronic\n• bstructive airways disease.\nYou are considering starting non-invasive ventilation (NIV).","parts":[{"id":"a","label":"Part A","prompt":"List 3 indications for initiating NIV in this patient. (3 marks)\n1) 2) 3) You have decided that NIV is appropriate for this patient."},{"id":"b","label":"Part B","prompt":"List 4 considerations in selecting your initial settings for NIV. (4 marks)\n1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"List 4 adjustments you might make to your original settings, including an indication for\neach. (4 marks) Adjustment Indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Type 1 resp failure</div><div class=\"answer-line\">Type 2 resp failure</div><div class=\"answer-line\">For severe fatigue in patient with ceiling of care (ie not-for intubation)</div><div class=\"answer-line\">As a pre-oxygenation/optimization strategy for patients requiring intubation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Oxygen requirement – will drive PEEP setting</div><div class=\"answer-line\">Degree of hypoxia – will determine initial FiO2 setting</div><div class=\"answer-line\">Work of breathing and tidal volume – will drive initial IPAP – EPAP differential (pressure support)</div><div class=\"answer-line\">Haemodynamics – PEEP will compromise preload and precipitate hypotension</div><div class=\"answer-line\">Patient tolerance/anxiety – may choose to start with lower settings for tolerance</div><div class=\"answer-line\">Pt usual settings</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Increase EPAP – for refractory hypoxia</div><div class=\"answer-line\">Increase IPAP – inadequate tidal volumes or poor clearance of CO2</div><div class=\"answer-line\">Decrease FiO2 – hyperoxia</div><div class=\"answer-line\">Increase FiO2 – hypoxia despite EPAP increase</div><div class=\"answer-line\">Decrease trigger flow rate – patient unable to trigger machine to achieve synchrony</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 40 year old man has presented with abdominal pain. He has a history of end-stage renal failure managed with peritoneal dialysis (PD).","parts":[{"id":"a","label":"Part A","prompt":"List 5 features of your assessment (history, examination, investigation) that would lead\nyou to request a CT scan of the abdomen. (5 marks) 1) 2) 3) 4) 5) Your provisional diagnosis is PD related peritonitis. You have arranged for a sample of peritoneal dialysate to be analysed in the laboratory."},{"id":"b","label":"Part B","prompt":"List 3 findings on fluid analysis that would indicate the presence of PD peritonitis.\n(3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ PD peritonitis has been confirmed as the diagnosis."},{"id":"c","label":"Part C","prompt":"List 3 considerations in selecting your initial antibiotic regime. (3 marks)\n1) 2) 3)\nPAH 2020.1 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">History of obstructive symptoms – faeculent vomiting; distention</div><div class=\"answer-line\">History c/w appendicitis eg shifting pain</div><div class=\"answer-line\">Recent Surgery ie tenckhoff insertion/replacement</div><div class=\"answer-line\">Focal Peritonism eg RIF / RUQ</div><div class=\"answer-line\">Clinical signs of shock state ie hypotension</div><div class=\"answer-line\">Obstructive jaundice</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Positive Gram Stain – single organism</div><div class=\"answer-line\">WCC &gt; 100 x 106</div><div class=\"answer-line\">PMNs &gt; 50%</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Known MRSA</div><div class=\"answer-line\">Allergies</div><div class=\"answer-line\">Prior cultures incl sensitivities</div><div class=\"answer-line\">Local protocol</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 25 year old man has been stabbed with a knife multiple times to the posterior trunk during a domestic dispute.\nHis vital signs on arrival are:\n\nGCS\n\nHR\n140 /min\n\nBP\n80/40 mmHg\n\nRR\n/min O2 sats 98% 15L O2 via NRB His chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State your interpretation of the chest x-ray, supported by 4 relevant radiographical abnormalities. (5 marks)"},{"id":"b","label":"Part B","prompt":"State the emergency procedure you would perform to manage the injury shown in the chest x-ray. (1 mark)"},{"id":"c","label":"Part C","prompt":"State 2 factors you will consider in determining the success of your procedure in managing the injury. (2 marks) 1) 2)"},{"id":"d","label":"Part D","prompt":"List 2 indications for surgical management of the injury demonstrated on the chest x-ray.\n(2 marks) 1) 2) Following your initial management, a CT scan has been performed. A slice from the CT abdomen has been provided in the PROPS BOOKLET."},{"id":"e","label":"Part E","prompt":"List 3 abnormalities evident on the CT slice. (3 marks)\n1) 2) 3) No other injuries were identified on assessment, and the patient’s vital signs returned to normal following your initial management. The patient has been awaiting admission to the acute surgical ward. After several hours in the ED, one of the nursing staff have notified you of recurrent hypotension."},{"id":"f","label":"Part F","prompt":"List 3 potential causes of recurrent hypotension in this patient. For each, state how you\nwill assess for its presence. (6 marks) Cause Assessment feature"}],"propPages":["asset:imgd7b0880252603545ed","asset:img4c330cd7248932b053"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>15/19</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Visible left lung edge</div><div class=\"answer-line\">Hyperinflation left hemithorax</div><div class=\"answer-line\">Homogenous opacification of left hemithorax</div><div class=\"answer-line\">Widespread subcutaneous emphysema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Left sided tube thoracostomy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">At point of procedure – decompression ie gush of air</div><div class=\"answer-line\">Clinical – trachea returns to midline, chest returns to normal symmetrical volume, return of breath</div><div class=\"answer-line\">sounds left side</div><div class=\"answer-line\">Haemodynamics – improved BP from R-sided filling</div><div class=\"answer-line\">Respiratory – normalization of RR, decreased work of breathing, improved oxygenation</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Ongoing persistent air-leak</div><div class=\"answer-line\">Large volume blood loss – 1500mls initial or ongoing &gt;200mls/hr for &gt;2hrs</div><div class=\"answer-line\">Treatment failure</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Left sided renal laceration</div><div class=\"answer-line\">Perinephric Haematoma</div><div class=\"answer-line\">Subcutaneous / intercostal haematoma  overlying retroperitoneal region</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Thoracic haemorrhage – ICC drain output, re-xray</td><td>Retroperitoneal haemorrhage – re-CT, check Hb</td></tr><tr><td><strong>Recurrent tension pneumothorax </strong></td><td>Any reasonable clinical feature</td></tr><tr><td>Others reasonable eg Distributive shock from anaphylaxis</td><td>Clinical signs anaphylaxis</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"An 83 year old man has presented after collapsing at the shops.\nOn arrival to the ED, he is alert with normal vital signs.","parts":[{"id":"a","label":"Part A","prompt":"List 4 examination findings that would suggest a cardiovascular cause of syncope. Include\nthe significance of each finding. (4 marks) 1) 2) 3) 4) An ECG is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List 2 key abnormalities on the ECG and state the relevance of these findings in the clinical context of this patient. (4 marks) Key abnormalities Clinical relevance"},{"id":"c","label":"Part C","prompt":"List 3 reversible causes that may be exacerbating this condition. (3 marks)"}],"propPages":["asset:imgcc7635e6ba8caf6cb3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Systolic Murmur c/w outflow obstruction eg AS / HOCM</div><div class=\"answer-line\">irregular pulse – eg AF – arrhythmogenic cause</div><div class=\"answer-line\">Signs of CCF (crackles, elevated JVP) – indicative of low CO state</div><div class=\"answer-line\">Signs of previous surgery (sternotomy) – high risk feature for arrhythmia</div><div class=\"answer-line\">Presence of pacemaker – potential intermittent failure</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Sinus rhythm with first degree AVB</div><div class=\"answer-line\"><strong>Left Bundle Branch Block </strong></div><div class=\"answer-line\"><strong>Incomplete TriFascicular Block</strong> – high risk for deterioration to complete AV Block</div><div class=\"answer-line\">Indication for pacemaker in absence of alternate cause for syncope</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ischaemia</div><div class=\"answer-line\">Electrolytes ie hyperkalaemia</div><div class=\"answer-line\">Medications ie CCBs, antiarrhythmics</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 3 week old boy has been brought to the ED after becoming unresponsive at home. The parents report decreased feeding over the last 2 days. Your provisional diagnosis is sepsis.","parts":[{"id":"a","label":"Part A","prompt":"Other than sepsis, list 5 potential differential diagnoses for this child’s presentation. For each, list one cardinal finding on your examination that would support the diagnosis. (10 marks) Diagnosis Examination finding"},{"id":"b","label":"Part B","prompt":"List 4 findings on an arterial blood gas that would influence your resuscitation of this child. For each, state how it would impact your management. (8 marks) Finding Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>13/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Endocrine – Addisonian crisis – signs of CAH ie hyperpigmented scrotum</td><td>Metabolic Disorder – hypoglycaemic – syndromic features</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Hyperkalaemia – IV calcium if broad QRS, shifting therapies ie salbutamol, insulin</td><td>Hypoxia – increase supplemental O2, consider intubation</td></tr><tr><td>Hypercapnoea – indication for mechanical ventilation</td><td>Others ie HypoNa, HAGMA etc ok only if justified in setting of resuscitation</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 72 year old woman has been brought to the ED due to concerns about her behaviour.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your mental status examination that would be consistent with delirium\nas a cause for abnormal behaviour. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ Your initial assessment is not consistent with delirium."},{"id":"b","label":"Part B","prompt":"List 5 features of your history or examination that would be consistent with a major\ndepressive disorder. (5 marks) 1) 2) 3) 4) 5) After a short period of time, the patient is wanting to leave the department."},{"id":"c","label":"Part C","prompt":"List 3 conditions that would need to be met to involuntarily detain the patient under a\nmental health act. (3 marks) 1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Altered conscious state</div><div class=\"answer-line\">Hallucinations eg visual</div><div class=\"answer-line\">Concentration loss</div><div class=\"answer-line\">Disorientation</div><div class=\"answer-line\">Agitation</div><div class=\"answer-line\">Fluctuation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Anhedonia</div><div class=\"answer-line\">Insomnia</div><div class=\"answer-line\">Prior admissions for depression</div><div class=\"answer-line\">Suicidal Ideation</div><div class=\"answer-line\">Loss of appetite</div><div class=\"answer-line\">Impaired cognition or concentration</div><div class=\"answer-line\">(accept most things from the MSE here)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">You believe the patient to have a mental illness</div><div class=\"answer-line\">Patient lacks the capacity to consent to treatment</div><div class=\"answer-line\">Patient assessed as a risk to themselves or others</div><div class=\"answer-line\">No less restrictive means to provide necessary mental health services</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 64 year old man has presented with epistaxis. The patient is taking rivaroxaban for stroke prophylaxis due to atrial fibrillation.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your history that will influence your management. Explain the relevance\n• f each. (4 marks)\n1) 2) 3) 4) Your assessment is consistent with large volume, ongoing, posterior epistaxis."},{"id":"b","label":"Part B","prompt":"State 2 treatment options for reversing the coagulopathy due to rivaroxaban. (2 marks)\n1) 2)"},{"id":"c","label":"Part C","prompt":"List 3 treatment options aimed at stopping the ongoing haemorrhage. For each, provide\nthe clinical indication. (6 marks) Treatment option Clinical indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Nature of epistaxis – ie unilateral vs bilateral – bilateral – posterior source</div><div class=\"answer-line\">History of nasal/facial trauma or surgery – as a source of bleeding</div><div class=\"answer-line\">Known focus for bleeding in nasopharyngeal carcinoma</div><div class=\"answer-line\">Timing of last dose of rivaroxaban – will indicate effectiveness of reversibility</div><div class=\"answer-line\">Volume/type of bleeding and first aid measures to date</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Prothrombin Complex Concentrate 25-50u/kg</div><div class=\"answer-line\">Tranexamic Acid 15-30mg/kg bolus + infusion</div><div class=\"answer-line\"><em>Recombinant Factor VIIa still in Qld guidelines at 50mcg/kg </em></div><div class=\"answer-line\"><em>Note: Andexanet Alfa is approved in US as direct-antibody reversal agent. </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Balloon tamponade with dual-balloon device ie 10cm rapid rhino</td><td>Indication: Suspected posterior bleeding, inadequate control with anterior balloon tamponade</td></tr><tr><td>Posterior nasopharyngeal gauze packing with IDC placement</td><td>Indication: failure to achieve control with anterior approach</td></tr><tr><td>Radiological embolization of bleeding vessel</td><td>Indication: Blush on CT(A) of face</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 56 year old man has been brought to the ED after crashing his motorcycle. He has a painful right shoulder, which is held in abduction. An x-ray of the right shoulder is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the injury demonstrated on the x-ray. (1 mark)"},{"id":"b","label":"Part B","prompt":"List and justify 3 key aspects of your examination of this man’s upper limb. (3 marks)\n1) 2) 3) You elect to undertake procedural sedation to manage the injury identified in the x-ray above and to allow further assessment for other injuries."},{"id":"c","label":"Part C","prompt":"State 5 key components of your pre-anaesthetic assessment prior to undertaking the\nprocedure. (5 marks) 1) 2) 3) 4) 5) The procedure was successful and no further injuries were identified on full assessment. After a period of observation, the patient is ready for discharge."},{"id":"d","label":"Part D","prompt":"List 3 components of your discharge advice. (3 marks)\n1) 2) 3)"}],"propPages":["asset:img9d1656050e213b3bf8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Luxatio Erectae (Inferior Shoulder Dislocation)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Sensation – risk of neuropraxia – axillary nerve</div><div class=\"answer-line\">Motor exam – risk of injury to branches of brachial plexus</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">History – cardiovascular status/fitness, valvular disease (partic. Ao Stenosis)</div><div class=\"answer-line\">Respiratory status – smoking, known lung disease or asthma</div><div class=\"answer-line\">Ability to lie flat ie reflux</div><div class=\"answer-line\"><strong>Allergies </strong></div><div class=\"answer-line\"><strong>Airway assessment</strong> – neck movement, loose teeth, mouth opening, mallampati or equivalent</div><div class=\"answer-line\">Fasting status</div><div class=\"answer-line\">Prior anaesthetic Hx ie problems, sux apnoea etc</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Need to ensure follow up ie refer to physio/upper limb clinic</div><div class=\"answer-line\">Advice re: when to seek urgent review (ie risk of axillary artery dissection/thrombus)</div><div class=\"answer-line\">Advice re: likely instability and activites to avoid/bracing</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 25 year old man has presented with a painful right eye.\nA photograph of his right eye is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities on the photograph. (3 marks)"},{"id":"b","label":"Part B","prompt":"State the most likely diagnosis. (1 mark)"},{"id":"c","label":"Part C","prompt":"List 2 pre-disposing factors for this condition. (2 marks)"},{"id":"d","label":"Part D","prompt":"List 3 complications of this condition. For each, state the examination finding that would suggest its presence. (6 marks) Complication Suggestive examination finding"}],"propPages":["asset:img4342e035fd2409840c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Cloudy anterior chamber</div><div class=\"answer-line\">Hypopion</div><div class=\"answer-line\">Irregular pupil</div><div class=\"answer-line\">Diffuse Conjunctival Injection</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Anterior Uveitis/ Iritis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Seroneg arthropathies (ie Ank Spondylitis)</div><div class=\"answer-line\">Inflammatory Bowel Disease</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Synechiae (likely already present)  irregular pupil, unresponsive to light</td><td>Cataracts  opacification of lens / loss light reflex</td></tr><tr><td>Posterior Uveitis  inability to visualize posterior structures</td><td>Optic neuritis  decreased vision</td></tr><tr><td>Glaucoma  Raised pressure</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"An 83 year old woman has been brought to the ED after being found on the floor at home. Her\nfamily last saw her 2 days ago.\nHer vital signs are:\n\nGCS\nE2 V3 M5\n\nTemp\n36.5 degrees Pulse /min\n\nBP\n110/65 mmHg\n\nRR\n/min O2 sats 92% room air","parts":[{"id":"a","label":"Part A","prompt":"List and justify 6 investigations you would perform on this patient. (12 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Both for causes ie CHB and complications (hyperK)</td></tr><tr><td>CK</td><td>Rhabdomyolysis</td></tr><tr><td><strong>K</strong> / chem 20</td><td>define hyper K, BSL</td></tr><tr><td>Chem20/ Renal Fn</td><td>Exclude renal injury</td></tr><tr><td>COAGs</td><td>Identify coagulopathy (unable to get med Hx with GCS 10)</td></tr><tr><td>CXR</td><td>Complications ie rib injuries, aspiration pneumonia</td></tr><tr><td><strong>CT Head</strong></td><td>Seek intracranial injury</td></tr><tr><td>CT C-Spine</td><td>Exclude cervical fracture</td></tr><tr><td>Pelvic XR</td><td>Exclude occult pelvic injury</td></tr><tr><td colspan=\"2\">Others likely ok if justified</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"You have been called to an acute cubicle where a 60 year old man has become unwell after receiving a dose of intravenous piperacillin/tazobactam. Your assessment is consistent with anaphylaxis. The patient’s vital signs are:\n\nGCS\nE3 V4 M6 Pulse 120 /min\n\nBP\n75/40 mmHg\n\nRR\n/min O2 sats 98% 15L O2 via non-rebreather mask","parts":[{"id":"a","label":"Part A","prompt":"State 2 components of your initial management, including end-points. (2 marks)\n1) 2) Upon reading the patient’s medical records, you note a documented penicillin allergy."},{"id":"b","label":"Part B","prompt":"List 2 other antibiotic classes that demonstrate allergen cross-reactivity with penicillins. For each class, state the incidence of cross-reactivity. (4 marks) Antibiotic Class Incidence of cross-reactivity Your anaphylaxis management was successful and the patient now has normal vital signs. He is asking about what happened."},{"id":"c","label":"Part C","prompt":"List 4 components of your response to his query. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Adrenaline 300-500mcg IM, repeat if needed aiming systolic &gt;100mmHg</div><div class=\"answer-line\">IV N/S 1000mL stat aiming systolic &gt;100mmHg</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cephalosporins – must be less than 10%</td><td>Carbapenems – 1%</td></tr><tr><td>Monobactams – less than 1%</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Open disclosure</div><div class=\"answer-line\">Apology</div><div class=\"answer-line\">Pledge to investigate</div><div class=\"answer-line\">Explain treatment</div><div class=\"answer-line\">Answer questions</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
